// === Tab: mySketch ===

var points = []
var runners = []
var tb_memory
var tb_variance


function setup() {
	noStroke()

	createCanvas(windowWidth, windowHeight);

	tb_memory = createSlider(0, 200, 15)
	tb_memory.position(10, 10)
	tb_variance = createSlider(0, 100000, 2000)
	tb_variance.position(10, 30)

	background(250);
	textSize(330)
	text("CORONA", 10, 400)

	for(i = 0; i < 720; i++) {
		while(true) {
			const x = random(0, windowWidth)
			const y = random(0, windowHeight)
			if(red(get(x, y)) < 5) {
				points.push(new Point(x, y))
				break
			}
		}
	}

	for(i = 0; i < 600; i++) {
		const p = Math.floor(random(0, points.length - 1))
		runners.push(new Runner(points[0]))
	}

	background(100);
}

function draw() {
	background(60, 60, 60, 12);

	noStroke()

	points.forEach(p => {
		const pop = p.popularity
		//fill(255, pop / 100.0)
		//ellipse(p.x, p.y, 2, 2);
		p.popularity -= 0.05 * (pop > 0)
	})

	fill(255, 80)
	runners.forEach(r => r.run())

}

class Point {
		constructor(x, y) {
			this.x = x
			this.y = y
			this.popularity = 0
		}

		distSquare(p) {
			const dx = p.x - this.x
			const dy = p.y - this.y
			return dx * dx + dy * dy
		}

		dist(p) {
			return Math.sqrt(this.distSquare(p))	
		}
}

class Runner {
		constructor(p) {
			this.path = [p, p, p, p]
			this.x = 0
			this.y = 0
			this.p1 = p
			this.p2 = p
			this.fac = 1
			this.v = random(1, 4)
			this.vfac = 0
		}

		nearest() {
			let n = Number.MAX_VALUE
			let pn = null
			const p1 = this.p1
			const p2 = this.p2
			points.forEach(p => {
				const d = p2.distSquare(p) + random(0, tb_variance.value() )//- p.popularity
				if(!this.path.includes(p) && d < n) {
					n = d
					pn = p
				}
			})
			return pn
		}

		run() {

			if(this.fac >= 1) {
				this.fac = 0
				this.p1 = this.p2
				this.p2 = this.nearest()
				this.p2.popularity += 3
				this.path.push(this.p2)
				while(this.path.length > tb_memory.value()) {
					this.path.shift()
				}

				this.vfac = this.v / this.path[this.path.length - 2].dist(this.path[this.path.length - 3])
			}

			const path = this.path
			const ix = path.length - 1
			const s1 = path[ix] 
			const s2 = path[ix - 1]
			const s3 = path[ix - 2]
			const s4 = path[ix - 3]

			this.fac += this.vfac
			//this.x = this.p1.x + (this.p2.x - this.p1.x) * this.fac
			//this.y = this.p1.y + (this.p2.y - this.p1.y) * this.fac

			this.x = curvePoint(s4.x, s3.x, s2.x, s1.x, this.fac)
			this.y = curvePoint(s4.y, s3.y, s2.y, s1.y, this.fac)

			ellipse(this.x, this.y, 2, 2)
			//stroke(200)
			//strokeWeight(1)
			//line(this.p1.x, this.p1.y, this.p2.x, this.p2.y)
		}
}

